/**
 * Writes docs/design/BLOG-IMAGE-BRIEFS.md: every blog image the designer still owes, read
 * from lib/blog-posts.ts, with file name, size, placement and brief. Images already staged
 * (present in lib/image-manifest.ts) are listed as delivered.
 *
 *   npx tsx scripts/blog-image-briefs.ts
 *
 * Run it after adding or editing a post's images, and after staging a delivery, then
 * commit the regenerated file. Hand-edits to the output are overwritten.
 */
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { BLOG_POSTS_NEWEST, blogImageStem, blogThumbStem, deliveredImage } from '../lib/blog-posts';
import { siteConfig } from '../lib/site-config';

const lines: string[] = [
  '# Blog image briefs',
  '',
  'Generated by `scripts/blog-image-briefs.ts` from `lib/blog-posts.ts`. Do not edit by hand.',
  '',
  'How to deliver:',
  '',
  '- Name each file exactly as listed (`blog-<post>-<n>`, `blog-thumb-<post>`), as JPEG for a photo',
  '  and PNG on a transparent background for a render.',
  '- Sizes: hero and figures 1600 × 900; card thumbnail 821 × 462.',
  '- Images are numbered in page order from the top: 1 is the hero, 2 the first figure below it.',
  '- Every slot shows its brief, in place, on any preview deployment and in local development. The',
  '  live site shows a stand-in or nothing until the file is delivered.',
  '- Faces must not be recognizable, and no screen may show a feature, number or brand the brief',
  '  does not ask for.',
  '',
];

let outstanding = 0;
for (const post of BLOG_POSTS_NEWEST) {
  const url = `${siteConfig.url}/blog/${post.slug}`;
  lines.push(`## ${post.title}`, '', `Page: ${url}`, '');
  const rows = [
    ...post.images.map((img) => ({
      stem: blogImageStem(post.slug, img.n),
      label: `Image ${img.n}${img.n === 1 ? ' (hero)' : ''}`,
      spec: img.kind === 'photo' ? 'photo, 1600 × 900 JPEG' : 'render, 1600 × 900 PNG, transparent background',
      placement: img.placement,
      brief: img.brief,
      done: Boolean(deliveredImage(blogImageStem(post.slug, img.n))),
    })),
    {
      stem: blogThumbStem(post.slug),
      label: 'Card thumbnail',
      spec: '821 × 462, PNG or JPEG',
      placement: 'The card for this post on /blog',
      brief: post.thumbBrief,
      done: Boolean(deliveredImage(blogThumbStem(post.slug))),
    },
  ];
  for (const r of rows) {
    if (!r.done) outstanding++;
    lines.push(
      `### ${r.label}: \`${r.stem}\`${r.done ? ' (delivered)' : ''}`,
      '',
      `- **Format:** ${r.spec}`,
      `- **Where:** ${r.placement}`,
      `- **Brief:** ${r.brief}`,
      '',
    );
  }
}

lines.splice(4, 0, `Outstanding: ${outstanding} image${outstanding === 1 ? '' : 's'}.`, '');
const out = path.join(process.cwd(), 'docs/design/BLOG-IMAGE-BRIEFS.md');
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${path.relative(process.cwd(), out)}: ${outstanding} outstanding.`);
